use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->SemioBrepSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let a=SemioPoint3{x:1.0,y:2.0,z:3.0};let b=SemioPoint3{x:0.0,y:0.0,z:1.0};let u=SemioPoint2{x:1.0,y:2.0};let v=SemioPoint2{x:3.0,y:4.0};let curves=vec![BrepCurve::Line{origin:a,direction:b},BrepCurve::Circle{center:a,axis:b,radius:2.5},BrepCurve::Ellipse{center:a,axis:b,radius_major:3.5,radius_minor:1.25},BrepCurve::Nurbs{control_points:vec![a,b],weights:vec![1.0,0.5],degree:1,knots:vec![0.0,0.0,1.0,1.0]}];let pcurves=vec![BrepCurve2::Line{origin:u,direction:v},BrepCurve2::Circle{center:u,radius:2.5},BrepCurve2::Ellipse{center:u,x_axis:v,radius_major:3.5,radius_minor:1.25},BrepCurve2::Nurbs{control_points:vec![u,v],weights:vec![1.0,0.5],degree:1,knots:vec![0.0,0.0,1.0,1.0]}];let surfaces=vec![BrepSurface::Plane{origin:a,normal:b},BrepSurface::Cylinder{origin:a,axis:b,radius:2.5},BrepSurface::Cone{origin:a,axis:b,radius:2.5,half_angle:0.25},BrepSurface::Sphere{center:a,radius:2.5},BrepSurface::Torus{center:a,axis:b,major_radius:3.5,minor_radius:1.25},BrepSurface::Nurbs{control_points:vec![a,b],weights:vec![1.0,0.5],u_count:1,v_count:2,degree_u:0,degree_v:1,knots_u:vec![0.0,1.0],knots_v:vec![0.0,0.0,1.0,1.0]}];SemioBrepSnapshot{schema:f["schema"].as_str().unwrap().into(),vertices:vec![BrepVertex{id:"v0".into(),point:a,tol:0.001},BrepVertex{id:"v-文".into(),point:b,tol:0.002}],edges:curves.into_iter().enumerate().map(|(i,curve)|BrepEdge{id:format!("e{i}"),start_vertex:"v0".into(),end_vertex:"v-文".into(),curve,tol:0.003}).collect(),loops:vec![BrepLoop{id:"loop".into(),edges:(0..4).map(|i|BrepLoopEdge{edge:format!("e{i}"),orientation:i%2==0}).collect()},BrepLoop{id:"inner".into(),edges:vec![]}],faces:surfaces.into_iter().enumerate().map(|(i,surface)|BrepFace{id:format!("f{i}"),outer_loop:"loop".into(),inner_loops:vec!["inner".into()],surface,orientation:i%2==0,tol:0.004}).collect(),shells:vec![BrepShell{id:"shell".into(),faces:(0..6).map(|i|BrepShellFace{face:format!("f{i}"),orientation:i%2==0}).collect()}],solids:vec![BrepSolid{id:"solid".into(),shells:vec![BrepSolidShell{shell:"shell".into(),is_void:false},BrepSolidShell{shell:"shell".into(),is_void:true}]}],coedges:pcurves.into_iter().enumerate().map(|(i,pcurve)|BrepCoedge{id:format!("c{i}"),edge:format!("e{i}"),forward:i%2==0,pcurve:Some(pcurve),prange:(-1.0,2.0),loop_id:"loop".into(),next:format!("c{}",(i+1)%4),prev:format!("c{}",(i+3)%4)}).collect(),next_label:f["nextLabel"].as_str().unwrap().parse().unwrap()}}
fn project(s:&SemioBrepSnapshot)->SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(db:&SqliteDatabase)->Result<SemioBrepSnapshot,String>{SemioBrepSnapshot::from_sqlite_database(db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
fn sqlite_snapshot_semio_brep_all_curves_surfaces_rings_labels_and_native_state(){let s=fixture();let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let r=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(r,s);assert_eq!(<SemioBrepSnapshot as store::ArtifactPack>::encode_pack(&r),<SemioBrepSnapshot as store::ArtifactPack>::encode_pack(&s));assert_eq!(<SemioBrepSnapshot as store::ArtifactDsl>::print_dsl(&r),<SemioBrepSnapshot as store::ArtifactDsl>::print_dsl(&s));let mut no_coedges=s.clone();no_coedges.coedges.clear();assert_eq!(restore(&project(&no_coedges)).unwrap(),no_coedges);assert_eq!(restore(&project(&SemioBrepSnapshot::default())).unwrap(),SemioBrepSnapshot::default());}
#[test]
fn sqlite_snapshot_semio_brep_rejects_dangling_topology_ring_shapes_and_budgets(){let original=project(&fixture());for change in 0..6{let mut db=original.clone();match change{0=>db.table_mut("semio_brep_edge").unwrap().rows[0].values[4]=SqliteValue::Integer(999),1=>db.table_mut("semio_brep_coedge").unwrap().rows[0].values[10]=SqliteValue::Integer(999),2=>db.table_mut("semio_brep_coedge").unwrap().rows[0].values[11]=SqliteValue::Integer(1),3=>db.table_mut("semio_brep_curve3").unwrap().rows[0].values[14]=SqliteValue::Real(1.0),4=>db.table_mut("semio_brep_surface_point").unwrap().rows[0].values[2]=SqliteValue::Integer(99),_=>db.table_mut("semio_brep_document").unwrap().rows[0].values[2]=SqliteValue::Text("018446744073709551615".into())}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_value_bytes:1,max_rows:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioBrepSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_brep_independent_curve_topology_and_label_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(db.query('SELECT count(*) AS n FROM semio_brep_coedge JOIN semio_brep_coedge AS next ON semio_brep_coedge.next_id=next.id WHERE next.previous_id=semio_brep_coedge.id').get().n!==4)throw Error('ring');if(db.query('SELECT kind FROM semio_brep_edge JOIN semio_brep_curve3 ON curve_id=semio_brep_curve3.id ORDER BY ordinal').all().map(r=>r.kind).join(',')!=='line,circle,ellipse,nurbs')throw Error('curve entities');db.query(\"UPDATE semio_brep_document SET next_label='18446744073709551614'\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let r=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();expected.next_label=u64::MAX-1;assert_eq!(r,expected);}

#[test]
fn sqlite_snapshot_semio_brep_bare_owner_capability_native_payload_bridge(){let snapshot=fixture();let payload=store::os_io::IoPayload::Binary(<SemioBrepSnapshot as store::ArtifactPack>::encode_pack(&snapshot));let codec=store::ArtifactCodec::bare::<SemioBrepSnapshot,crate::standards::v1::subsets::brep::schema::mutations::SemioBrepMutation>("s.stdio.semio.brep");let provider=codec.snapshot_sqlite.expect("owner must publish typed SQLite capability");assert_eq!(provider.snapshot_type,Some(std::any::TypeId::of::<SemioBrepSnapshot>()));let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"brep".into()};let db=(provider.export)("s.stdio.semio.brep",&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let db=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=(provider.import)("s.stdio.semio.brep",&dialect,db,SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(actual,payload);}

#[test]
fn sqlite_snapshot_semio_brep_owned_numeric_bits_independent_sqlite(){use std::io::Write;use std::process::{Command,Stdio};let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for(index,bits)in f["float64Bits"].as_array().unwrap().iter().enumerate(){let bits=u64::from_str_radix(bits.as_str().unwrap(),16).unwrap();let bits32=u32::from_str_radix(f["float32Bits"][index].as_str().unwrap(),16).unwrap();let v=f64::from_bits(bits);let _v32=f32::from_bits(bits32);let mut s=fixture();s.vertices[0].point.x=v;let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');await Bun.write(Bun.stdout,d.serialize());d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let r=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!((r.vertices[0].point.x).to_bits(),bits);assert_eq!(<SemioBrepSnapshot as store::ArtifactPack>::encode_pack(&r),<SemioBrepSnapshot as store::ArtifactPack>::encode_pack(&s));}}

#[test]
fn sqlite_snapshot_semio_brep_typed_exact_subset_dialect_and_document_guard(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let snapshot=fixture();let database=project(&snapshot);let dialect=|v:&serde_json::Value|store::os_io::ArtifactDialect{artifact_kind:v["artifactKind"].as_str().unwrap().into(),standard:v["standard"].as_str().unwrap().into(),subset:v["subset"].as_str().unwrap().into()};let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&database,&mut control).unwrap().diagnostics.is_empty());for invalid in f["invalidSqliteDialects"].as_array().unwrap(){assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(invalid),&database,&mut control).is_err());}let mut malformed=database;malformed.table_mut("semio_brep_document").unwrap().rows[0].values[1]=SqliteValue::Text("other schema".into());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&malformed,&mut control).is_err());}

#[test]
fn sqlite_snapshot_semio_brep_bounded_native_text_binary_admission() {
    let snapshot=fixture();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"brep".into()};
    let provider=<SemioBrepSnapshot as store::ArtifactPack>::sqlite_snapshot_codec().unwrap();
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{
        snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let actual=(provider.import)("Semio native admission",&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;
        let expected=match encoding{SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioBrepSnapshot as store::ArtifactDsl>::print_dsl(&snapshot)),SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioBrepSnapshot as store::ArtifactPack>::encode_pack(&snapshot))};assert_eq!(actual,expected);
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());
    }
    let large= SemioBrepSnapshot{schema:"x".repeat(100000),..snapshot};
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()})).is_err());
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |p|p.phase!=SqliteSnapshotPhase::EncodeNative||p.completed==0,SqliteDatabaseLimits::default())).is_err());
}
